import sys
from collections import defaultdict, deque

def bfs(tree, start):
    dist = [-1] * (len(tree) + 1)
    dist[start] = 0
    queue = deque([start])
    while queue:
        node = queue.popleft()
        for neighbor in tree[node]:
            if dist[neighbor] == -1:
                dist[neighbor] = dist[node] + 1
                queue.append(neighbor)
    return dist

def max_cool_sequence_length(tree, dists, P, Q):
    max_len = 0
    for root in range(1, len(tree) + 1):
        dp = [0] * (len(tree) + 1)
        dp[root] = (dists[root][P], dists[root][Q])
        for d in range(1, len(tree) + 1):
            for node in range(1, len(tree) + 1):
                if dp[node][0] == d:
                    for neighbor in tree[node]:
                        if dists[node][neighbor] == d + 1:
                            dp[neighbor] = max(dp[neighbor], (dp[node][0] + 1, dp[node][1]))
                            if neighbor == Q:
                                max_len = max(max_len, dp[neighbor][0])
    return max_len

def main():
    import sys
    input = sys.stdin.read().split()
    idx = 0
    N = int(input[idx])
    M = int(input[idx + 1])
    idx += 2
    tree = defaultdict(list)
    for _ in range(N - 1):
        U = int(input[idx])
        V = int(input[idx + 1])
        tree[U].append(V)
        tree[V].append(U)
        idx += 2
    dists = [bfs(tree, i) for i in range(1, N + 1)]
    queries = []
    for _ in range(M):
        P = int(input[idx])
        Q = int(input[idx + 1])
        queries.append((P, Q))
        idx += 2
    results = []
    for P, Q in queries:
        results.append(max_cool_sequence_length(tree, dists, P, Q))
    print('\n'.join(map(str, results)))

main()
